custom_css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Space+Grotesk:wght@600;700&display=swap');

/* обязательное: палитра для ВСЕХ окон */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
  --t-bg: #141318;
  --t-bg-subtle: #1c1a24;
  --t-bg-card: #23202d;
  --t-ink: #ffffff;
  --t-dim: #ffadc6;
  --t-accent: #ff2d78;
  --t-accent-hover: #ff5493;
  --t-line: rgba(255, 60, 130, 0.28);
  --t-line-strong: rgba(255, 60, 130, 0.5);

  --mt-accent: var(--t-accent);
  --mt-accent-hover: var(--t-accent-hover);
  --mt-bg-primary: var(--t-bg);
  --mt-bg-secondary: var(--t-bg-card);
  --mt-bg-input: var(--t-bg-subtle);
  --mt-border: var(--t-line);

  --mt-text: var(--t-ink);
  --mt-text-dim: var(--t-dim);
  --mt-text-on-accent: #ffffff;
  --mt-overlay: rgba(8, 7, 12, 0.78);
  --mt-modal-shadow: 0 18px 40px rgba(0, 0, 0, 0.75), 0 0 0 1px var(--t-line);
  --mt-text-strong: var(--t-ink);
  --mt-divider: var(--t-line);

  --mt-pl-spotify-tab: #1db954;
  --mt-pl-spotify-tab-text: #ffffff;
}

.mt-progress {
  --mt-slider-track: #2a2533;
  --mt-slider-track-height: 4px;
  --mt-slider-track-radius: 99px;
  --mt-slider-progress: #ff2d78;
  --mt-slider-thumb-size: 13px;
  --mt-slider-thumb-bg: #ffffff;
  --mt-slider-thumb-bg-hover: #ff5493;
  --mt-slider-thumb-border: 2px solid #ff2d78;
  --mt-slider-thumb-radius: 50%;
  --mt-slider-thumb-shadow: 0 0 8px rgba(255, 45, 120, 0.6);
}

.mt-volume {
  --mt-slider-track: #2a2533;
  --mt-slider-track-height: 3px;
  --mt-slider-track-radius: 99px;
  --mt-slider-progress: #ff5493;
  --mt-slider-thumb-size: 10px;
  --mt-slider-thumb-bg: #ff5493;
  --mt-slider-thumb-bg-hover: #ffffff;
  --mt-slider-thumb-border: none;
  --mt-slider-thumb-radius: 50%;
  --mt-slider-thumb-shadow: none;
}

/* обязательное: плеер (БЕЗ position/top/left/width/height) */
.mt-player {
  container-type: size;
  padding: 36px 18px 14px;
  background: radial-gradient(circle at 50% -10%, rgba(255, 45, 120, 0.16), transparent 60%), #141318;
  border: 1px solid var(--t-line);
  border-radius: 16px;
  color: var(--t-ink);
  font-family: 'Inter', sans-serif;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.65), 0 0 18px rgba(255, 45, 120, 0.08);
  backdrop-filter: none;
}

.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }
#moodtube-mini-player, #moodtube-mini-player *, #mt-settings-modal, #mt-settings-modal *, .mt-fab, .mt-fab *, .mt-pl-modal, .mt-pl-modal * {
  text-shadow: none;
}

.mt-player-header {
  top: 14px;
  left: 18px;
  right: 96px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.mt-player-header-title {
  font-family: 'Space Grotesk', 'Inter', sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #ffadc6;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mt-player-status {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: #ffffff;
  background: rgba(255, 45, 120, 0.28);
  border: 1px solid rgba(255, 45, 120, 0.5);
  padding: 2px 6px;
  border-radius: 4px;
  white-space: nowrap;
  flex-shrink: 0;
}

/* Кнопки окна (верхний правый угол) */
.mt-window-btn {
  width: 20px;
  height: 20px;
  font-size: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--t-dim);
  border: none;
  background: transparent;
  cursor: pointer;
  padding: 0;
  line-height: 1;
  box-sizing: border-box;
  transition: color .2s, translate .15s;
}
.mt-window-btn:hover { color: var(--t-accent); translate: 0 -1px; }
.mt-window-btn:active { translate: 0 1px; }
.mt-btn-close:hover { color: #ff3344; }

/* Обложка трека (винил с круглой сердцевиной) */
.mt-cover {
  width: 136px;
  height: 136px;
  margin: 0 auto;
  position: relative;
  border-radius: 50%;
  overflow: visible;
  background: radial-gradient(circle, #1e1c24 0%, #111015 44%, #282432 47%, #111015 50%, #201c28 68%, #0d0c10 100%);
  border: 2px solid rgba(255, 60, 130, 0.4);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.65), inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  flex-shrink: 0;
  animation: spin 12s linear infinite;
  animation-play-state: paused;
}
.mt-player.mt-is-playing .mt-cover {
  animation-play-state: running;
}
@keyframes spin {
  to { rotate: 360deg; }
}

.mt-slot-cover-bg, .mt-slot-cover {
  background: transparent;
}
.mt-slot-decor {
  z-index: 1;
  pointer-events: none;
}

img.mt-cover-img {
  position: absolute;
  left: 22%;
  top: 22%;
  width: 56%;
  height: 56%;
  border-radius: 50%;
  object-fit: cover;
  z-index: 1;
  border: 2px solid #ff2d78;
}

.mt-cover-hole {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 12px;
  height: 12px;
  translate: -50% -50%;
  border-radius: 50%;
  background: #141318;
  border: 2px solid #ffadc6;
  z-index: 3;
}

/* Информация о треке */
.mt-track-info {
  position: relative;
  text-align: center;
  padding: 0 28px;
}
.mt-track-title {
  font-family: 'Space Grotesk', 'Inter', sans-serif;
  font-size: 14px;
  font-weight: 700;
  color: #ffffff;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.mt-track-subtitle {
  font-size: 11px;
  font-weight: 500;
  color: #ffadc6;
  margin-top: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Кнопка «Избранное» (сердечко без фона и рамок) */
.mt-btn-favorite {
  position: absolute;
  right: 0;
  top: 50%;
  translate: 0 -50%;
  width: 24px;
  height: 24px;
  padding: 0;
  background: none;
  border: none;
  box-shadow: none;
  color: rgba(255, 173, 198, 0.4);
  font-size: 16px;
  cursor: pointer;
  transition: color .2s, scale .15s;
  display: flex;
  align-items: center;
  justify-content: center;
}
.mt-btn-favorite:hover {
  color: #ff5493;
  scale: 1.15;
}
.mt-btn-favorite.mt-is-active {
  color: #ff2d78;
}

/* Прогресс-бар */
.mt-progress {
  display: flex;
  align-items: center;
  gap: 8px;
}
.mt-time-current, .mt-time-total {
  font-size: 10px;
  font-weight: 600;
  color: var(--t-dim);
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

/* обязательное: кнопки (width + height + font-size у КАЖДОЙ) */
.mt-controls {
  gap: 8px;
  justify-content: center;
  display: flex;
  align-items: center;
}
.mt-controls > .mt-btn {
  width: 32px;
  height: 32px;
  font-size: 13px;
  padding: 0;
  line-height: 1;
  box-sizing: border-box;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #1c1a24;
  border: 1px solid rgba(255, 60, 130, 0.32);
  color: #ffffff;
  cursor: pointer;
  transition: background .18s, border-color .18s, color .18s, translate .15s;
}
.mt-controls > .mt-btn:hover {
  background: rgba(255, 45, 120, 0.2);
  border-color: #ff5493;
  color: #ffadc6;
  translate: 0 -1px;
}
.mt-controls > .mt-btn:active {
  translate: 0 1px;
}

.mt-controls > .mt-btn-play {
  width: 42px;
  height: 42px;
  font-size: 15px;
  background: linear-gradient(135deg, #ff2d78, #ff5493);
  border: none;
  color: #ffffff;
  box-shadow: 0 4px 14px rgba(255, 45, 120, 0.45);
}
.mt-controls > .mt-btn-play:hover {
  background: linear-gradient(135deg, #ff3c84, #ff66a1);
  box-shadow: 0 6px 18px rgba(255, 45, 120, 0.6);
  color: #ffffff;
  translate: 0 -1px;
}
.mt-controls > .mt-btn-play:active {
  translate: 0 1px;
  box-shadow: 0 2px 8px rgba(255, 45, 120, 0.4);
}
.mt-btn-play.fa-play { padding-left: 2px; }

.mt-btn-ai.mt-is-busy {
  color: #ff2d78;
  animation: mt-pulse 1s infinite alternate;
}
@keyframes mt-pulse {
  to { scale: 1.1; color: #ff5493; }
}

/* Громкость */
.mt-volume {
  display: flex;
  align-items: center;
  gap: 8px;
}
.mt-volume-low, .mt-volume-high {
  font-size: 11px;
  color: var(--t-dim);
  flex-shrink: 0;
}

/* обязательное: панели, окна */
.mt-panel {
  background: #141318;
  color: var(--t-ink);
  padding-top: 40px;
  border-radius: inherit;
}
.mt-panel-search { --mt-bg-primary: #141318; }
.mt-queue-dislike { background-color: var(--t-dim); }
.mt-pl-modal-box {
  background: #141318;
  border: 1px solid var(--t-line);
  border-radius: 14px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.75), 0 0 0 1px var(--t-line);
}
#mt-settings-modal .mt-flex-container {
  background: #141318;
  border: 1px solid var(--t-line);
  border-radius: 14px;
  box-shadow: 0 20px 48px rgba(0, 0, 0, 0.85);
}
#mt-settings-modal .mt-btn-test {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: #ff2d78;
  color: #ffffff;
  border: none;
  border-radius: 8px;
  padding: 8px 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background .15s, translate .1s;
}
#mt-settings-modal .mt-btn-test:hover {
  background: #ff5493;
  translate: 0 -1px;
}
#mt-settings-modal .mt-btn-test:active {
  translate: 0 1px;
}

/* Очередь воспроизведения */
.mt-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px 10px;
  border-bottom: 1px solid var(--t-line);
}
.mt-panel-title {
  font-family: 'Space Grotesk', 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: #ffffff;
}
.mt-panel-close {
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  color: var(--t-dim);
  font-size: 13px;
  cursor: pointer;
  transition: color .15s;
}
.mt-panel-close:hover { color: #ff5493; }

.mt-panel-list {
  padding: 8px 10px;
  counter-reset: mt-q-count;
}
.mt-queue-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 8px;
  transition: background .15s;
  counter-increment: mt-q-count;
}
.mt-queue-item::before {
  content: counter(mt-q-count);
  font-size: 10px;
  font-weight: 700;
  color: var(--t-dim);
  width: 14px;
  text-align: center;
  flex-shrink: 0;
}
.mt-queue-item:hover {
  background: rgba(255, 45, 120, 0.08);
}
.mt-queue-item.mt-is-current {
  background: rgba(255, 45, 120, 0.16);
  border-left: 3px solid #ff2d78;
}
.mt-queue-item.mt-is-current::before {
  color: #ff2d78;
}
.mt-queue-thumb {
  width: 32px;
  height: 32px;
  border-radius: 6px;
  object-fit: cover;
  flex-shrink: 0;
}
.mt-queue-title {
  flex: 1;
  font-size: 12px;
  font-weight: 600;
  color: #ffffff;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mt-queue-now {
  color: #ff2d78;
  font-size: 12px;
  flex-shrink: 0;
}
.mt-queue-add {
  color: var(--t-dim);
  font-size: 12px;
  cursor: pointer;
  transition: color .15s;
  flex-shrink: 0;
}
.mt-queue-add:hover { color: #ff5493; }
.mt-queue-dislike {
  width: 13px;
  height: 13px;
  flex-shrink: 0;
  cursor: pointer;
  transition: background-color .15s;
}
.mt-queue-dislike:hover {
  background-color: #ff3344;
}

/* Плейлисты */
.mt-pl-tabs {
  display: flex;
  gap: 6px;
  padding: 0 14px 10px;
  border-bottom: 1px solid var(--t-line);
}
.mt-pl-tab {
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  color: var(--t-dim);
  background: #1c1a24;
  border: 1px solid var(--t-line);
  cursor: pointer;
  transition: all .15s;
}
.mt-pl-tab:hover {
  border-color: #ff5493;
  color: #ffffff;
}
.mt-pl-tab.mt-is-active {
  background: #ff2d78;
  border-color: #ff2d78;
  color: #ffffff;
}
.mt-playlist-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 8px;
  transition: background .15s;
}
.mt-playlist-item:hover {
  background: rgba(255, 45, 120, 0.08);
}
.mt-playlist-title {
  color: #ffffff;
  font-size: 12px;
  font-weight: 600;
  flex: 1;
}
.mt-pl-cover {
  width: 34px;
  height: 34px;
  border-radius: 6px;
  object-fit: cover;
  flex-shrink: 0;
}
.mt-pl-toolbar .mt-pl-tool {
  background: none;
  border: none;
  color: var(--t-dim);
  font-size: 13px;
  cursor: pointer;
  transition: color .15s;
}
.mt-pl-toolbar .mt-pl-tool:hover { color: #ff5493; }

/* Поиск */
#moodtube-search-input {
  background: #1c1a24;
  color: #ffffff;
  border: 1px solid var(--t-line);
}
#moodtube-search-go {
  background: #ff2d78;
  color: var(--mt-text-on-accent);
  border: none;
  transition: background .15s;
}
#moodtube-search-go:hover {
  background: #ff5493;
}

/* Окно «Добавить в плейлист» */
.mt-pl-modal-track {
  font-weight: 700;
  color: #ffffff;
}
.mt-pl-option {
  color: #ffadc6;
  border: 1px solid var(--t-line);
  border-radius: 8px;
  background: #1c1a24;
  transition: all .15s;
}
.mt-pl-option:hover {
  background: rgba(255, 45, 120, 0.14);
  border-color: #ff5493;
  color: #ffffff;
}
.mt-pl-option.mt-is-added {
  background: #ff2d78;
  border-color: #ff2d78;
  color: #ffffff;
}

/* Окно настроек */
#mt-settings-modal .mt-header h3 {
  color: #ffffff;
  font-weight: 700;
}
#mt-settings-modal .mt-close {
  color: var(--t-dim);
  transition: color .15s;
}
#mt-settings-modal .mt-close:hover {
  color: #ff5493;
}
#mt-settings-modal .mt-subpanel {
  background: #1c1a24;
  border: 1px solid var(--t-line);
  border-radius: 10px;
}
.mt-tag, .mt-genre-tag, .mt-mood-tag, .mt-scenario-tag {
  background: #1c1a24;
  border: 1px solid var(--t-line);
  color: #ffadc6;
  border-radius: 6px;
  padding: 4px 8px;
  transition: all .15s;
}
.mt-tag:hover, .mt-genre-tag:hover, .mt-mood-tag:hover, .mt-scenario-tag:hover {
  border-color: #ff5493;
  color: #ffffff;
}
.mt-tag.active, .mt-genre-tag.active, .mt-mood-tag.active, .mt-scenario-tag.active {
  background: #ff2d78;
  border-color: #ff2d78;
  color: #ffffff;
  font-weight: 600;
}

/* Плавающая кнопка (FAB) */
.mt-fab {
  background: linear-gradient(135deg, #ff2d78, #ff5493);
  border: 2px solid rgba(255, 255, 255, 0.25);
  color: #ffffff;
  box-shadow: 0 6px 20px rgba(255, 45, 120, 0.5);
  transition: translate .15s, box-shadow .15s;
}
.mt-fab:hover {
  translate: 0 -2px;
  box-shadow: 0 8px 24px rgba(255, 45, 120, 0.7);
}

/* Скроллбары */
.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar, .mt-pl-modal-box ::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track, .mt-pl-modal-box ::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.15);
}
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb, .mt-pl-modal-box ::-webkit-scrollbar-thumb {
  background: rgba(255, 60, 130, 0.4);
  border-radius: 99px;
}
.mt-player ::-webkit-scrollbar-thumb:hover, #mt-settings-modal ::-webkit-scrollbar-thumb:hover, .mt-pl-modal-box ::-webkit-scrollbar-thumb:hover {
  background: #ff2d78;
}

/* Контейнерные запросы и режимы */
@container (max-width: 300px) {
  .mt-player .mt-player-status { display: none; }
}

@container (max-width: 640px) {
  .mt-player.moodtube-row-layout .mt-volume { display: none; }
}

/* Широкая полоса (.moodtube-row-layout) */
.mt-player.moodtube-row-layout {
  padding: 30px 16px 12px;
}
.mt-player.moodtube-row-layout .mt-player-body {
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.mt-player.moodtube-row-layout .mt-cover {
  width: 54px;
  height: 54px;
  margin: 0;
  flex-shrink: 0;
}
.mt-player.moodtube-row-layout .mt-track-info {
  min-width: 100px;
  max-width: 140px;
  flex: 1 1 auto;
  text-align: left;
  padding: 0 24px 0 0;
}
.mt-player.moodtube-row-layout .mt-progress {
  min-width: 90px;
  flex: 1 1 auto;
}
.mt-player.moodtube-row-layout .mt-controls {
  gap: 6px;
  flex-shrink: 0;
}
.mt-player.moodtube-row-layout .mt-controls > .mt-btn {
  width: 28px;
  height: 28px;
  font-size: 12px;
}
.mt-player.moodtube-row-layout .mt-controls > .mt-btn-play {
  width: 34px;
  height: 34px;
  font-size: 13px;
}

/* Компактный режим (маленькое окно / маленький квадрат 200x200) */
@container (max-width: 190px) {
  .mt-controls { gap: 4px; }
  .mt-controls > .mt-btn { width: 26px; height: 26px; font-size: 11px; }
  .mt-controls > .mt-btn-play { width: 30px; height: 30px; font-size: 12px; }
}

@container (max-width: 190px) or (max-height: 250px) {
  .mt-player:not(.moodtube-row-layout) .mt-player-body {
    gap: 8px;
  }
  .mt-player:not(.moodtube-row-layout) .mt-cover {
    width: 64px;
    height: 64px;
  }
  .mt-player:not(.moodtube-row-layout) .mt-volume {
    display: none;
  }
  .mt-player:not(.moodtube-row-layout) .mt-track-title {
    font-size: 12px;
  }
  .mt-player:not(.moodtube-row-layout) .mt-track-subtitle {
    font-size: 10px;
  }
}

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'Inter', sans-serif;
  --mt-dock-cover-radius: 50%;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 50%;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
